  'privacyPolicy.toc.howCollect': { en: 'How We Collect Personal Data', mm: 'ကျွန်ုပ်တို့သည် ကိုယ်ရေးကိုယ်တာအချက်အလက်များကို မည်သို့စုဆောင်းသနည်း' },
