  'aboutApp.ourMission': { en: 'Our Mission', mm: 'ကျွန်ုပ်တို့၏ မျှော်မှန်းချက်' },
  'aboutApp.missionDescription': { en: 'At Jade Property, our mission is to revolutionize the real estate experience in Myanmar by providing a transparent, efficient, and user-friendly platform that empowers individuals and businesses to discover, buy, sell, and manage properties with confidence. We leverage cutting-edge technology and local expertise to deliver exceptional service and value to our community.', mm: 'Jade Property တွင်၊ ကျွန်ုပ်တို့၏ မျှော်မှန်းချက်မှာ ပွင့်လင်းမြင်သာသော၊ ထိရောက်သော၊ နှင့် အသုံးပြုရလွယ်ကူသော ပလက်ဖောင်းကို ပေးအပ်ခြင်းဖြင့် မြန်မာနိုင်ငံရှိ အိမ်ခြံမြေအတွေ့အကြုံကို တော်လှန်ပြောင်းလဲရန်ဖြစ်ပြီး၊ လူတစ်ဦးချင်းနှင့် စီးပွားရေးလုပ်ငန်းများအား ယုံကြည်မှုဖြင့် အိမ်ခြံမြေများကို ရှာဖွေ၊ ဝယ်ယူ၊ ရောင်းချ၊ နှင့် စီမံခန့်ခွဲနိုင်စေရန် အားပေးပါသည်။ ကျွန်ုပ်တို့သည် ထူးခြားသော ဝန်ဆောင်မှုနှင့် တန်ဖိုးကို ကျွန်ုပ်တို့၏ အသိုင်းအဝိုင်းသို့ ပေးအပ်ရန် အဆင့်မြင့် နည်းပညာနှင့် ဒေသတွင်း ကျွမ်းကျင်မှုကို အသုံးပြုပါသည်။' },
